import{c as a,Q as s,j as e,m as n}from"./chunks/framework.DOi4mjdC.js";const u=JSON.parse('{"title":"Gather","description":"","frontmatter":{},"headers":[{"level":1,"title":"Gather","slug":"gather"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/Memory矢量计算/离散与聚合/Gather.md","filePath":"api/SIMD-API/基础API/Memory矢量计算/离散与聚合/Gather.md"}'),l={name:"api/SIMD-API/基础API/Memory矢量计算/离散与聚合/Gather.md"};function i(p,t,d,c,o,r){return s(),e("div",null,[...t[0]||(t[0]=[n(`<h1 id="gather" tabindex="-1">Gather <a class="header-anchor" href="#gather" aria-label="Permalink to &quot;Gather&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>√</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>给定输入的张量和一个地址偏移张量，本接口根据偏移地址将输入张量按元素收集到结果张量中。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><ul><li><p>tensor前n个数据计算</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T&gt;</span></span>
<span class="line"><span>__aicore__ inline void Gather(const LocalTensor&lt;T&gt;&amp; dst, const LocalTensor&lt;T&gt;&amp; src, const LocalTensor&lt;uint32_t&gt;&amp; srcOffset, const uint32_t srcBaseOffset, const uint32_t count)</span></span></code></pre></div></li><li><p>tensor高维切分计算</p><ul><li><p>mask逐bit模式</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T&gt;</span></span>
<span class="line"><span>__aicore__ inline void Gather(const LocalTensor&lt;T&gt;&amp; dst, const LocalTensor&lt;T&gt;&amp; src, const LocalTensor&lt;uint32_t&gt;&amp; srcOffset, const uint32_t srcBaseOffset, const uint64_t mask[], const uint8_t repeatTime, const uint16_t dstRepStride)</span></span></code></pre></div></li><li><p>mask连续模式</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T&gt;</span></span>
<span class="line"><span>__aicore__ inline void Gather(const LocalTensor&lt;T&gt;&amp; dst, const LocalTensor&lt;T&gt;&amp; src, const LocalTensor&lt;uint32_t&gt;&amp; srcOffset, const uint32_t srcBaseOffset, const uint64_t mask, const uint8_t repeatTime, const uint16_t dstRepStride)</span></span></code></pre></div></li></ul></li></ul><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>操作数数据类型。 Ascend 950PR/Ascend 950DT，支持的数据类型为：uint8_t/int8_t/uint16_t/int16_t/half/bfloat16_t/uint32_t/int32_t/float/uint64_t/int64_t Atlas A3 训练系列产品/Atlas A3 推理系列产品，支持的数据类型为：int16_t/uint16_t/int32_t/uint32_t/float/half/bfloat16_t Atlas A2 训练系列产品/Atlas A2 推理系列产品，支持的数据类型为：int16_t/uint16_t/int32_t/uint32_t/float/half/bfloat16_t Atlas 200I/500 A2 推理产品，支持的数据类型为：uint8_t/int8_t/uint16_t/int16_t/half/uint32_t/int32_t/float Atlas 推理系列产品AI Core，支持的数据类型为：int16_t/uint16_t/int32_t/uint32_t/float/half</td></tr></tbody></table><p><strong>表 2</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 LocalTensor的起始地址需要32字节对齐。</td></tr><tr><td>src</td><td>输入</td><td>源操作数。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 LocalTensor的起始地址需要32字节对齐。 数据类型和dst保持一致。</td></tr><tr><td>srcBaseOffset</td><td>输入</td><td>每个元素在src中对应的地址偏移。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 LocalTensor的起始地址需要32字节对齐。 该偏移量相对于src的起始基地址而言。单位为Bytes。取值要求如下： 取值应保证src元素类型位宽对齐。偏移地址后不能超出UB大小数据的范围。针对以下型号，地址偏移的取值范围：不能超出uint32_t的范围。 Atlas 推理系列产品AI Core Atlas A2 训练系列产品/Atlas A2 推理系列产品 Atlas A3 训练系列产品/Atlas A3 推理系列产品 针对以下型号，地址偏移的取值范围：当操作数为8位时，取值范围为[0, 216-1]；当操作数为16位时，取值范围为[0, 217-1]，当操作数为32位或者64位时，不能超出uint32_t的范围。 Atlas 200I/500 A2 推理产品 Ascend 950PR/Ascend 950DT</td></tr><tr><td>srcBaseAddr</td><td>输入</td><td>src的起始基地址，用于指定Gather操作中源操作数的起始位置，单位为Bytes。取值应保证src元素类型位宽对齐，否则会导致非预期行为。</td></tr><tr><td>count</td><td>输入</td><td>执行处理的数据个数。</td></tr><tr><td>mask/mask[]</td><td>输入</td><td>mask用于控制每次迭代内参与计算的元素。 连续模式：表示前面连续的多少个元素参与计算。取值范围和操作数的数据类型有关，数据类型不同，每次迭代内能够处理的元素个数最大值不同。当操作数为8位或16位时，mask∈[1, 128]；当操作数为32位时，mask∈[1, 64]；当操作数为64位时，mask∈[1, 32]。 逐bit模式：可以按位控制哪些元素参与计算，bit位的值为1表示参与计算，0表示不参与。参数类型为长度为2的uint64_t类型数组。 例如，mask=[8, 0]，8=0b1000，表示仅第4个元素参与计算。 参数取值范围和操作数的数据类型有关，数据类型不同，每次迭代内能够处理的元素个数最大值不同。当操作数为8位或16位时，mask[0]、mask[1]∈[0, 264-1]并且不同时为0；当操作数为32位时，mask[1]为0，mask[0]∈(0, 264-1]；当操作数为64位时，mask[1]为0，mask[0]∈(0, 232-1]。</td></tr><tr><td>repeatTime</td><td>输入</td><td>指令迭代次数，每次迭代完成8个datablock（32Bytes）的数据收集，数据范围：repeatTime∈[0,255]。 特别地，针对以下型号：Atlas 200I/500 A2 推理产品Ascend 950PR/Ascend 950DT 操作数为8位时，每次迭代完成4个datablock（32Bytes）的数据收集。</td></tr><tr><td>dstRepStride</td><td>输入</td><td>相邻迭代间的地址步长，单位是datablock（32Bytes）。</td></tr></tbody></table><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li><p>操作数地址对齐要求请参见<a href="./../../../通用说明和约束.html#section796754519912">通用地址对齐约束</a>。</p></li><li><p>操作数地址重叠约束请参考<a href="./../../../通用说明和约束.html#section668772811100">通用地址重叠约束</a>。</p></li><li><p>针对Ascend 950PR/Ascend 950DT，uint8_t/int8_t数据类型仅支持tensor前n个数据计算接口。</p></li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>本样例中只展示Compute流程中的部分代码。如果您需要运行样例代码，请将该代码段拷贝并替换<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/02_features/03_basic_api/02_memory_vector_compute/gather" target="_blank" rel="noreferrer">Gather类样例</a>场景三中Compute函数的部分代码即可。</p><ul><li><p>tensor高维切分计算样例-mask连续模式</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// repeatTime = 4, mask = 128, 128 elements one repeat, 512 elements total</span></span>
<span class="line"><span>// srcLocal数据类型为half，srcOffsetLocal数据类型为uint32_t，dstLocal数据类型为half</span></span>
<span class="line"><span>// srcBaseAddr = 0, srcLocal的起始基地址为0</span></span>
<span class="line"><span>// dstRepStride = 8, no gap between repeats </span></span>
<span class="line"><span>AscendC::Gather(dstLocal, srcLocal, srcOffsetLocal, (uint32_t)0, 128, 4, 8);</span></span></code></pre></div></li><li><p>tensor高维切分计算样例-mask逐bit模式</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>uint64_t mask[2] = { 0xFFFFFFFFFFFFFFFF, 0xFFFFFFFFFFFFFFFF };</span></span>
<span class="line"><span>// repeatTime = 4, 128 elements one repeat, 512 elements total</span></span>
<span class="line"><span>// srcLocal数据类型为half，srcOffsetLocal数据类型为uint32_t，dstLocal数据类型为half</span></span>
<span class="line"><span>// srcBaseAddr = 0, srcLocal的起始基地址为0</span></span>
<span class="line"><span>// dstRepStride = 8, no gap between repeats </span></span>
<span class="line"><span>AscendC::Gather(dstLocal, srcLocal, srcOffsetLocal, (uint32_t)0, mask, 4, 8);</span></span></code></pre></div></li><li><p>tensor前n个数据计算样例</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>uint32_t count = 512;    // 参与计算的元素个数</span></span>
<span class="line"><span>// srcLocal数据类型为half，srcOffsetLocal数据类型为uint32_t，dstLocal数据类型为half</span></span>
<span class="line"><span>// srcBaseAddr = 0, srcLocal的起始基地址为0</span></span>
<span class="line"><span>AscendC::Gather(dstLocal, srcLocal, srcOffsetLocal, (uint32_t)0, count);</span></span></code></pre></div></li></ul><p>结果示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入数据srcOffsetLocal:</span></span>
<span class="line"><span>[254 252 250 ... 4 2 0]</span></span>
<span class="line"><span>输入数据srcLocal（128个half类型数据）: </span></span>
<span class="line"><span>[0 1 2 ... 125 126 127]</span></span>
<span class="line"><span>输出数据(dstLocal)初始值:</span></span>
<span class="line"><span>[0. 0. 0. 0. 0. 0. ... 0.]</span></span>
<span class="line"><span>进行Gather计算后，输出数据(dstLocal):</span></span>
<span class="line"><span>[127 126 125 ... 2 1 0]</span></span></code></pre></div>`,19)])])}const _=a(l,[["render",i]]);export{u as __pageData,_ as default};
